/**
 * useDocumentLines.js
 * ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
 * Shared composable for managing document line items across all procurement
 * document types (IPR, RFQ, PO, GRN).
 *
 * Provides:
 *   - Reactive `lines` array with add / remove helpers
 *   - Financial computeds: subtotal, totalTax, grandTotal
 *   - Currency-aware formatting helper
 *
 * Usage:
 *   const {
 *     lines, addBlankLine, addCatalogItems, removeLine,
 *     subtotal, totalTax, grandTotal, formatCurrency,
 *   } = useDocumentLines('ipr')
 *
 * This composable works ALONGSIDE `use-document-edit.js` ΓÇö it does NOT
 * replace it.  The edit composable owns the form object; this composable
 * can optionally be used to manage just the lines slice.
 */

import { computed, ref } from 'vue'

/**
 * Field-name mappings per document type.
 * Allows each document to use its own DB column names while the composable
 * stays generic.
 */
const FIELD_MAP = {
  ipr: { qty: 'qty_requested', price: 'estimated_unit_cost', discount: null, tax: null },
  rfq: { qty: 'qty_requested', price: 'target_price_ht', discount: null, tax: null },
  po:  { qty: 'qty_ordered',   price: 'unit_price',        discount: 'discount_pct', tax: 'tax_rate_pct' },
  grn: { qty: 'qty_received',  price: 'unit_cost_ht',      discount: null, tax: null },
}

/**
 * @param {'ipr'|'rfq'|'po'|'grn'} documentType
 * @param {import('vue').Ref<Array>} [externalLines] ΓÇö optional external ref to bind to
 *        (e.g. `computed(() => form.value.lines)`)
 */
export function useDocumentLines(documentType, externalLines) {
  const fields = FIELD_MAP[documentType] || FIELD_MAP.ipr

  // If no external ref is provided, create our own reactive array
  const lines = externalLines || ref([])

  // ΓöÇΓöÇ Mutations ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  /**
   * Add a blank line with sensible defaults.
   */
  const addBlankLine = () => {
    lines.value.push({
      _key: Date.now(),
      catalog_item_id: null,
      catalog_item: null,
      is_ad_hoc: true,
      ad_hoc_name: '',
      ad_hoc_sku: 'NEW',
      description: '',
      uom: '',
      [fields.qty]: 1,
      [fields.price]: null,
      ...(fields.discount ? { [fields.discount]: 0 } : {}),
      ...(fields.tax ? { [fields.tax]: 0 } : {}),
      notes: '',
    })
  }

  /**
   * Merge an array of catalog-line objects (typically from CatalogPickerModal).
   * @param {Array<object>} catalogLines ΓÇö pre-shaped line objects
   */
  const addCatalogItems = catalogLines => {
    lines.value.push(...catalogLines)
  }

  /**
   * Remove a line by index.
   * @param {number} index
   */
  const removeLine = index => {
    lines.value.splice(index, 1)
  }

  // ΓöÇΓöÇ Financials ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  const subtotal = computed(() =>
    lines.value.reduce((sum, line) => {
      const qty = parseFloat(line[fields.qty]) || 0
      const price = parseFloat(line[fields.price]) || 0
      const discount = fields.discount ? (parseFloat(line[fields.discount]) || 0) / 100 : 0

      return sum + qty * price * (1 - discount)
    }, 0),
  )

  const totalTax = computed(() =>
    lines.value.reduce((sum, line) => {
      if (!fields.tax) return sum

      const qty = parseFloat(line[fields.qty]) || 0
      const price = parseFloat(line[fields.price]) || 0
      const discount = fields.discount ? (parseFloat(line[fields.discount]) || 0) / 100 : 0
      const taxRate = (parseFloat(line[fields.tax]) || 0) / 100

      return sum + qty * price * (1 - discount) * taxRate
    }, 0),
  )

  const grandTotal = computed(() => subtotal.value + totalTax.value)

  // ΓöÇΓöÇ Formatting ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  /**
   * Format a numeric value as currency.
   * @param {number|string} value
   * @param {string} [currency='TND']
   * @returns {string}
   */
  const formatCurrency = (value, currency = 'TND') => {
    const num = parseFloat(value) || 0

    return `${num.toFixed(3)} ${currency}`
  }

  // ΓöÇΓöÇ Public API ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  return {
    lines,
    addBlankLine,
    addCatalogItems,
    removeLine,
    subtotal,
    totalTax,
    grandTotal,
    formatCurrency,
  }
}
